import { describe, it, expect } from "vitest";

// Simulates a minimal package.json dependency map as it would be parsed at runtime
type DependencyMap = Record<string, string>;

interface PackageJson {
  dependencies?: DependencyMap;
  devDependencies?: DependencyMap;
}

const APM_PACKAGES = [
  "@opentelemetry/api",
  "@opentelemetry/sdk-node",
  "dd-trace",
  "newrelic",
  "@honeycombio/opentelemetry-node",
];

const ERROR_TRACKING_PACKAGES = [
  "@sentry/node",
  "@sentry/browser",
  "@sentry/nextjs",
  "rollbar",
  "bugsnag",
  "@bugsnag/js",
];

function detectObservabilityStack(pkg: PackageJson): {
  hasAPM: boolean;
  hasErrorTracking: boolean;
  missingObservability: boolean;
} {
  const allDeps = {
    ...pkg.dependencies,
    ...pkg.devDependencies,
  };

  const depNames = Object.keys(allDeps);

  const hasAPM = APM_PACKAGES.some((p) => depNames.includes(p));
  const hasErrorTracking = ERROR_TRACKING_PACKAGES.some((p) =>
    depNames.includes(p)
  );

  return {
    hasAPM,
    hasErrorTracking,
    missingObservability: !hasAPM && !hasErrorTracking,
  };
}

function initErrorTracking(deps: DependencyMap): string[] {
  const warnings: string[] = [];

  const hasErrorTracking = ERROR_TRACKING_PACKAGES.some((p) =>
    Object.keys(deps).includes(p)
  );

  if (!hasErrorTracking) {
    warnings.push(
      "ERROR: No error tracking detected. Crashes will go unnoticed in production."
    );
    warnings.push(
      "FIX: Add @sentry/node and initialise Sentry.init() at application startup."
    );
  }

  return warnings;
}

function initAPM(deps: DependencyMap): string[] {
  const warnings: string[] = [];

  const hasAPM = APM_PACKAGES.some((p) => Object.keys(deps).includes(p));

  if (!hasAPM) {
    warnings.push(
      "ERROR: No APM/tracing library detected. You cannot correlate latency with deployments."
    );
    warnings.push(
      "FIX: Add @opentelemetry/sdk-node and configure a trace exporter."
    );
  }

  return warnings;
}

describe("Observability stack detection", () => {
  it("foot-gun: project with no observability deps produces warnings and flags missing stack", () => {
    const barePackageJson: PackageJson = {
      dependencies: {
        express: "4.18.2",
        lodash: "4.17.21",
        axios: "1.6.0",
      },
      devDependencies: {
        typescript: "5.0.0",
        vitest: "1.0.0",
      },
    };

    const result = detectObservabilityStack(barePackageJson);

    expect(result.hasAPM).toBe(false);
    expect(result.hasErrorTracking).toBe(false);
    expect(result.missingObservability).toBe(true);

    const allDeps = {
      ...barePackageJson.dependencies,
      ...barePackageJson.devDependencies,
    } as DependencyMap;

    const errorWarnings = initErrorTracking(allDeps);
    const apmWarnings = initAPM(allDeps);

    expect(errorWarnings.length).toBeGreaterThan(0);
    expect(errorWarnings[0]).toMatch(/No error tracking detected/);

    expect(apmWarnings.length).toBeGreaterThan(0);
    expect(apmWarnings[0]).toMatch(/No APM\/tracing library detected/);
  });

  it("safe fix: project with Sentry + OpenTelemetry passes all observability checks", () => {
    const instrumentedPackageJson: PackageJson = {
      dependencies: {
        express: "4.18.2",
        "@sentry/node": "7.80.0",
        "@opentelemetry/api": "1.7.0",
        "@opentelemetry/sdk-node": "0.45.0",
      },
      devDependencies: {
        typescript: "5.0.0",
        vitest: "1.0.0",
      },
    };

    const result = detectObservabilityStack(instrumentedPackageJson);

    expect(result.hasAPM).toBe(true);
    expect(result.hasErrorTracking).toBe(true);
    expect(result.missingObservability).toBe(false);

    const allDeps = {
      ...instrumentedPackageJson.dependencies,
      ...instrumentedPackageJson.devDependencies,
    } as DependencyMap;

    const errorWarnings = initErrorTracking(allDeps);
    const apmWarnings = initAPM(allDeps);

    expect(errorWarnings).toHaveLength(0);
    expect(apmWarnings).toHaveLength(0);
  });

  it("partial fix: only Sentry present still flags missing APM", () => {
    const partialPackageJson: PackageJson = {
      dependencies: {
        express: "4.18.2",
        "@sentry/node": "7.80.0",
      },
    };

    const result = detectObservabilityStack(partialPackageJson);

    expect(result.hasAPM).toBe(false);
    expect(result.hasErrorTracking).toBe(true);
    expect(result.missingObservability).toBe(false); // at least one tool present

    const allDeps = { ...partialPackageJson.dependencies } as DependencyMap;
    const apmWarnings = initAPM(allDeps);

    expect(apmWarnings.length).toBeGreaterThan(0);
    expect(apmWarnings[0]).toMatch(/No APM\/tracing library detected/);
  });

  it("partial fix: only OpenTelemetry present still flags missing error tracking", () => {
    const partialPackageJson: PackageJson = {
      dependencies: {
        express: "4.18.2",
        "@opentelemetry/api": "1.7.0",
        "@opentelemetry/sdk-node": "0.45.0",
      },
    };

    const result = detectObservabilityStack(partialPackageJson);

    expect(result.hasAPM).toBe(true);
    expect(result.hasErrorTracking).toBe(false);
    expect(result.missingObservability).toBe(false); // at least one tool present

    const allDeps = { ...partialPackageJson.dependencies } as DependencyMap;
    const errorWarnings = initErrorTracking(allDeps);

    expect(errorWarnings.length).toBeGreaterThan(0);
    expect(errorWarnings[0]).toMatch(/No error tracking detected/);
  });
});

import { describe, it, expect } from "vitest";

// Synthetic simulation of a minimal analytics abstraction.
// We recreate the foot-gun (no telemetry = silent feature adoption)
// and the safe fix (a lightweight event-tracking wrapper).

// --- Foot-gun: no analytics instrumentation ---
function signupUserWithoutTelemetry(username: string): { user: string; events: string[] } {
  // User signs up but no event is tracked anywhere
  return { user: username, events: [] };
}

function activateFeatureWithoutTelemetry(feature: string): { feature: string; events: string[] } {
  // Feature is activated but adoption is invisible
  return { feature, events: [] };
}

// --- Safe fix: lightweight analytics wrapper (PostHog-style interface) ---
type AnalyticsEvent = { event: string; properties: Record<string, unknown> };

class AnalyticsClient {
  private captured: AnalyticsEvent[] = [];

  capture(event: string, properties: Record<string, unknown> = {}): void {
    this.captured.push({ event, properties });
  }

  getCaptured(): AnalyticsEvent[] {
    return this.captured;
  }

  reset(): void {
    this.captured = [];
  }
}

const analytics = new AnalyticsClient();

function signupUserWithTelemetry(username: string): { user: string } {
  analytics.capture("signup", { username, timestamp: 0 });
  return { user: username };
}

function activateFeatureWithTelemetry(feature: string, userId: string): { feature: string } {
  analytics.capture("activation", { feature, userId, timestamp: 0 });
  return { feature };
}

function recordFirstValueMoment(userId: string, action: string): void {
  analytics.capture("first_value_moment", { userId, action, timestamp: 0 });
}

function recordChurnSignal(userId: string, reason: string): void {
  analytics.capture("churn_signal", { userId, reason, timestamp: 0 });
}

describe("Product analytics telemetry", () => {
  it("demonstrates the foot-gun: no events are captured without telemetry instrumentation", () => {
    const result = signupUserWithoutTelemetry("alice");
    expect(result.user).toBe("alice");
    // No events tracked — feature adoption is completely invisible
    expect(result.events).toHaveLength(0);

    const featureResult = activateFeatureWithoutTelemetry("dark-mode");
    expect(featureResult.feature).toBe("dark-mode");
    // Still no events — you cannot close the loop between code shipped and value delivered
    expect(featureResult.events).toHaveLength(0);
  });

  it("safe fix: key lifecycle events are captured with a PostHog-style analytics client", () => {
    analytics.reset();

    // Track the 5 key events recommended by the rule
    signupUserWithTelemetry("bob");
    activateFeatureWithTelemetry("dark-mode", "bob");
    recordFirstValueMoment("bob", "created-first-project");
    // Simulate a retention event
    analytics.capture("retention", { userId: "bob", sessionCount: 3 });
    recordChurnSignal("bob", "pricing");

    const events = analytics.getCaptured();

    // All 5 key events are present
    const eventNames = events.map((e) => e.event);
    expect(eventNames).toContain("signup");
    expect(eventNames).toContain("activation");
    expect(eventNames).toContain("first_value_moment");
    expect(eventNames).toContain("retention");
    expect(eventNames).toContain("churn_signal");
    expect(events).toHaveLength(5);

    // Verify properties are attached for context
    const signupEvent = events.find((e) => e.event === "signup");
    expect(signupEvent?.properties.username).toBe("bob");

    const activationEvent = events.find((e) => e.event === "activation");
    expect(activationEvent?.properties.feature).toBe("dark-mode");
    expect(activationEvent?.properties.userId).toBe("bob");

    const churnEvent = events.find((e) => e.event === "churn_signal");
    expect(churnEvent?.properties.reason).toBe("pricing");
  });

  it("safe fix: analytics client accumulates events across multiple users", () => {
    analytics.reset();

    signupUserWithTelemetry("carol");
    signupUserWithTelemetry("dave");
    activateFeatureWithTelemetry("export-csv", "carol");

    const events = analytics.getCaptured();
    expect(events).toHaveLength(3);

    const signups = events.filter((e) => e.event === "signup");
    expect(signups).toHaveLength(2);
    expect(signups.map((e) => e.properties.username)).toEqual(["carol", "dave"]);
  });
});

import { describe, it, expect } from "vitest";

// Synthetic simulation of an auth endpoint handler with and without rate limiting

interface AuthRequest {
  ip: string;
  username: string;
  password: string;
}

interface AuthResponse {
  success: boolean;
  message: string;
  statusCode: number;
}

// --- FOOT-GUN: Auth handler with NO rate limiting ---
function unprotectedAuthHandler(
  request: AuthRequest,
  _attemptCount: number
): AuthResponse {
  // Simulates a real password check (always fails for wrong password)
  const VALID_USER = "admin";
  const VALID_PASS = "supersecret";

  if (request.username === VALID_USER && request.password === VALID_PASS) {
    return { success: true, message: "Authenticated", statusCode: 200 };
  }
  // No rate limiting: every attempt is processed regardless of how many have been made
  return { success: false, message: "Invalid credentials", statusCode: 401 };
}

// --- SAFE FIX: Auth handler WITH rate limiting and account locking ---
interface RateLimitStore {
  attempts: Map<string, number>;
  lockedAccounts: Set<string>;
}

function createRateLimitStore(): RateLimitStore {
  return {
    attempts: new Map(),
    lockedAccounts: new Set(),
  };
}

const RATE_LIMIT_PER_IP = 5;       // max attempts per IP per window
const ACCOUNT_LOCK_THRESHOLD = 10; // lock account after N failures

function protectedAuthHandler(
  request: AuthRequest,
  store: RateLimitStore
): AuthResponse {
  const { ip, username, password } = request;

  // Check account lock
  if (store.lockedAccounts.has(username)) {
    return { success: false, message: "Account locked", statusCode: 423 };
  }

  // Check IP rate limit
  const ipAttempts = store.attempts.get(ip) ?? 0;
  if (ipAttempts >= RATE_LIMIT_PER_IP) {
    return { success: false, message: "Too many requests", statusCode: 429 };
  }

  // Record attempt
  store.attempts.set(ip, ipAttempts + 1);

  const VALID_USER = "admin";
  const VALID_PASS = "supersecret";

  if (username === VALID_USER && password === VALID_PASS) {
    // Reset on success
    store.attempts.delete(ip);
    return { success: true, message: "Authenticated", statusCode: 200 };
  }

  // Track per-account failures for locking
  const accountKey = `account:${username}`;
  const accountFailures = (store.attempts.get(accountKey) ?? 0) + 1;
  store.attempts.set(accountKey, accountFailures);
  if (accountFailures >= ACCOUNT_LOCK_THRESHOLD) {
    store.lockedAccounts.add(username);
  }

  return { success: false, message: "Invalid credentials", statusCode: 401 };
}

describe("Auth Endpoints Not Rate Limited", () => {
  it("demonstrates the foot-gun: unprotected handler allows unlimited brute-force attempts", () => {
    const passwords = [
      "password1", "password2", "password3", "letmein", "admin123",
      "qwerty", "abc123", "monkey", "dragon", "master",
      "sunshine", "princess", "welcome", "shadow", "superman",
      "michael", "football", "baseball", "iloveyou", "trustno1",
    ];

    const results: AuthResponse[] = [];

    // Simulate an AI agent or attacker hammering the endpoint with no throttling
    for (let i = 0; i < passwords.length; i++) {
      const response = unprotectedAuthHandler(
        { ip: "1.2.3.4", username: "admin", password: passwords[i] },
        i + 1
      );
      results.push(response);
    }

    // All 20 attempts are processed — no 429, no lockout
    const blockedResponses = results.filter(
      (r) => r.statusCode === 429 || r.statusCode === 423
    );
    expect(blockedResponses.length).toBe(0); // DANGER: nothing is blocked

    // Every failed attempt returns 401, meaning the attacker can keep trying forever
    const unauthorizedResponses = results.filter((r) => r.statusCode === 401);
    expect(unauthorizedResponses.length).toBe(passwords.length);
  });

  it("safe fix: rate limiter blocks IP after 5 attempts per window", () => {
    const store = createRateLimitStore();
    const results: AuthResponse[] = [];

    for (let i = 0; i < 10; i++) {
      const response = protectedAuthHandler(
        { ip: "1.2.3.4", username: "admin", password: `wrong${i}` },
        store
      );
      results.push(response);
    }

    // First 5 attempts should return 401 (processed but failed)
    const processedAttempts = results.slice(0, RATE_LIMIT_PER_IP);
    processedAttempts.forEach((r) => {
      expect(r.statusCode).toBe(401);
    });

    // Attempts 6-10 should be rate-limited with 429
    const rateLimitedAttempts = results.slice(RATE_LIMIT_PER_IP);
    rateLimitedAttempts.forEach((r) => {
      expect(r.statusCode).toBe(429);
      expect(r.message).toBe("Too many requests");
    });
  });

  it("safe fix: account is locked after 10 failed attempts from different IPs", () => {
    const store = createRateLimitStore();
    const results: AuthResponse[] = [];

    // Simulate 10 different IPs each making one failed attempt against the same account
    for (let i = 0; i < ACCOUNT_LOCK_THRESHOLD; i++) {
      const response = protectedAuthHandler(
        { ip: `10.0.0.${i}`, username: "victim", password: `attempt${i}` },
        store
      );
      results.push(response);
    }

    // After 10 failures the account should be locked
    expect(store.lockedAccounts.has("victim")).toBe(true);

    // Any further attempt — even from a new IP — should be rejected with 423
    const postLockResponse = protectedAuthHandler(
      { ip: "99.99.99.99", username: "victim", password: "anythingAtAll" },
      store
    );
    expect(postLockResponse.statusCode).toBe(423);
    expect(postLockResponse.message).toBe("Account locked");
  });

  it("safe fix: successful authentication resets the IP rate-limit counter", () => {
    const store = createRateLimitStore();

    // Make 3 failed attempts
    for (let i = 0; i < 3; i++) {
      protectedAuthHandler(
        { ip: "5.5.5.5", username: "admin", password: "wrong" },
        store
      );
    }
    expect(store.attempts.get("5.5.5.5")).toBe(3);

    // Successful login resets the counter
    const successResponse = protectedAuthHandler(
      { ip: "5.5.5.5", username: "admin", password: "supersecret" },
      store
    );
    expect(successResponse.statusCode).toBe(200);
    expect(successResponse.success).toBe(true);
    expect(store.attempts.has("5.5.5.5")).toBe(false);
  });
});
